diff --git a/conversation/retry.go b/conversation/retry.go
new file mode 100644
index 0000000..f3fe75d
--- /dev/null
+++ b/conversation/retry.go
@@ -0,0 +1,86 @@
+package conversation
+
+import (
+	"context"
+	"errors"
+	"net/http"
+	"slices"
+	"unicode/utf8"
+)
+
+// RetryProvider is application-owned policy, scheduling and authority. Reads
+// are observations; preference changes and cancellation must be idempotent.
+type RetryProvider interface {
+	ReadRetry(context.Context, string) (RetryStatus, error)
+	SetRetryEnabled(context.Context, string, bool) (RetryStatus, error)
+	CancelRetry(context.Context, string) (RetryStatus, error)
+}
+
+// RetryStatus carries safe presentation only, never native routing or options.
+// NextAttemptAtMS is null when there is no deadline. ServerNowMS lets a browser
+// display the deadline without relying on its wall clock matching the server.
+type RetryStatus struct {
+	Enabled         bool   `json:"enabled"`
+	Class           string `json:"class"`
+	Phase           string `json:"phase"`
+	Attempt         int    `json:"attempt"`
+	NextAttemptAtMS *int64 `json:"nextAttemptAtMs"`
+	ServerNowMS     int64  `json:"serverNowMs"`
+	CyberUsed       int    `json:"cyberUsed"`
+	CyberLimit      int    `json:"cyberLimit"`
+	Reason          string `json:"reason"`
+}
+
+func (handler *Handler) retry(response http.ResponseWriter, request *http.Request, target Target, operation string) {
+	if !target.Capabilities.Retry ||
+		(operation == "retry" && request.Method != http.MethodGet) ||
+		(operation != "retry" && request.Method != http.MethodPost) {
+		handler.rejectOperation(response, request)
+		return
+	}
+	if target.Retry == nil {
+		writeError(response, http.StatusNotFound, "retry is unavailable")
+		return
+	}
+	var state RetryStatus
+	var err error
+	switch operation {
+	case "retry":
+		state, err = target.Retry.ReadRetry(request.Context(), target.ThreadID)
+	case "retry/enabled":
+		var body struct {
+			Enabled *bool `json:"enabled"`
+		}
+		if !handler.decode(response, request, &body) {
+			return
+		}
+		if body.Enabled == nil {
+			writeError(response, http.StatusBadRequest, "enabled must be a boolean")
+			return
+		}
+		state, err = target.Retry.SetRetryEnabled(request.Context(), target.ThreadID, *body.Enabled)
+	case "retry/cancel":
+		if !handler.decodeEmpty(response, request) {
+			return
+		}
+		state, err = target.Retry.CancelRetry(request.Context(), target.ThreadID)
+	}
+	if err != nil {
+		handler.serverError(response, request, errors.New("retry provider operation failed"))
+		return
+	}
+	if !validRetryStatus(state) {
+		handler.serverError(response, request, errors.New("retry provider returned invalid status"))
+		return
+	}
+	writeJSON(response, http.StatusOK, state)
+}
+
+func validRetryStatus(state RetryStatus) bool {
+	return slices.Contains([]string{"", "capacity", "cybersecurity"}, state.Class) &&
+		slices.Contains([]string{"idle", "scheduled", "submitting", "reconciling", "running", "cancelled", "exhausted", "blocked"}, state.Phase) &&
+		state.Attempt >= 0 && state.ServerNowMS > 0 &&
+		(state.NextAttemptAtMS == nil || *state.NextAttemptAtMS > 0) &&
+		state.CyberUsed >= 0 && state.CyberUsed <= state.CyberLimit && state.CyberLimit == 30 &&
+		len(state.Reason) <= 1024 && utf8.ValidString(state.Reason)
+}
diff --git a/conversation/retry_test.go b/conversation/retry_test.go
new file mode 100644
index 0000000..6d491de
--- /dev/null
+++ b/conversation/retry_test.go
@@ -0,0 +1,126 @@
+package conversation
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"log"
+	"net/http"
+	"net/http/httptest"
+	"strings"
+	"testing"
+)
+
+type retryFixture struct {
+	state                RetryStatus
+	thread               string
+	reads, sets, cancels int
+	err                  error
+	lock                 *retryFixtureLock
+}
+
+type retryFixtureLock struct{ held bool }
+
+func (l *retryFixtureLock) Lock(context.Context) error { l.held = true; return nil }
+func (l *retryFixtureLock) Unlock()                    { l.held = false }
+func (f *retryFixture) ReadRetry(_ context.Context, thread string) (RetryStatus, error) {
+	f.thread = thread
+	f.reads++
+	return f.state, f.err
+}
+func (f *retryFixture) SetRetryEnabled(_ context.Context, thread string, enabled bool) (RetryStatus, error) {
+	if !f.lock.held {
+		return RetryStatus{}, errors.New("mutation lock missing")
+	}
+	f.thread = thread
+	f.sets++
+	f.state.Enabled = enabled
+	return f.state, f.err
+}
+func (f *retryFixture) CancelRetry(_ context.Context, thread string) (RetryStatus, error) {
+	if !f.lock.held {
+		return RetryStatus{}, errors.New("mutation lock missing")
+	}
+	f.thread = thread
+	f.cancels++
+	f.state.Phase = "cancelled"
+	return f.state, f.err
+}
+
+func TestRetryRoutesRequireTrustedCapabilityOriginAndPayload(t *testing.T) {
+	for _, test := range []struct {
+		name, method, path, body, origin string
+		grant, provider                  bool
+		status, calls                    int
+	}{
+		{"read", "GET", "retry", "", "", true, true, 200, 1},
+		{"enable", "POST", "retry/enabled", `{"enabled":true}`, "https://trusted.test", true, true, 200, 1},
+		{"cancel", "POST", "retry/cancel", `{}`, "https://trusted.test", true, true, 200, 1},
+		{"denied", "GET", "retry", "", "", false, true, 403, 0},
+		{"optional absent", "GET", "retry", "", "", true, false, 404, 0},
+		{"cross origin", "POST", "retry/cancel", `{}`, "https://evil.test", true, true, 403, 0},
+		{"missing origin", "POST", "retry/cancel", `{}`, "", true, true, 403, 0},
+		{"no enabled", "POST", "retry/enabled", `{}`, "https://trusted.test", true, true, 400, 0},
+		{"null enabled", "POST", "retry/enabled", `{"enabled":null}`, "https://trusted.test", true, true, 400, 0},
+		{"extra input", "POST", "retry/enabled", `{"enabled":true,"threadId":"evil"}`, "https://trusted.test", true, true, 400, 0},
+		{"cancel cannot send", "POST", "retry/cancel", `{"message":"continue"}`, "https://trusted.test", true, true, 400, 0},
+		{"wrong verb", "GET", "retry/cancel", "", "", true, true, 403, 0},
+	} {
+		t.Run(test.name, func(t *testing.T) {
+			lock := &retryFixtureLock{}
+			provider := &retryFixture{lock: lock, state: RetryStatus{Enabled: true, Phase: "idle", ServerNowMS: 1000, CyberLimit: 30}}
+			var selected RetryProvider = provider
+			if !test.provider {
+				selected = nil
+			}
+			handler, err := NewHandler(Options{AllowedOrigins: []string{"https://trusted.test"}, Resolver: ResolverFunc(func(_ context.Context, request ResolveRequest) (Target, error) {
+				if request.ID != "opaque" || request.Operation != test.path {
+					t.Fatalf("request=%+v", request)
+				}
+				return Target{Client: &fakeClient{}, ThreadID: "trusted-thread", Directory: "/trusted", MutationLock: lock, Retry: selected, Capabilities: Capabilities{Retry: test.grant}}, nil
+			})})
+			if err != nil {
+				t.Fatal(err)
+			}
+			request := httptest.NewRequest(test.method, "/codex/conversations/opaque/"+test.path, strings.NewReader(test.body))
+			if test.origin != "" {
+				request.Header.Set("Origin", test.origin)
+			}
+			response := httptest.NewRecorder()
+			handler.ServeHTTP(response, request)
+			if response.Code != test.status || provider.reads+provider.sets+provider.cancels != test.calls {
+				t.Fatalf("status=%d body=%s calls=%d/%d/%d", response.Code, response.Body.String(), provider.reads, provider.sets, provider.cancels)
+			}
+			if test.calls > 0 && provider.thread != "trusted-thread" {
